export default async function run(ctx) {
  await ctx.page.goto("https://timeline.test/home");

  const posts = await ctx.page.evalExtract("article", {
    text: { selector: "[data-testid='postText']" },
    url: { selector: "a[href*='/status/']", attr: "href" },
  });
  for (const post of posts) {
    await ctx.emitIfNew("post.detected", post, { dedupeKey: post.url });
  }
}
